-- Metadata only. Do not add customer rows, stored document contents or secrets.
begin read only;
select jsonb_build_object(
 'tables',(select jsonb_agg(table_name) from information_schema.tables where table_schema='public' and table_type='BASE TABLE'),
 'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef)) from pg_indexes where schemaname='public' and tablename in ('reservations','invoices','quotation_versions')),
 'integrity_counts',jsonb_build_object('duplicate_quotation_bookings',(select count(*) from (select quotation_id from public.reservations where quotation_id is not null group by quotation_id having count(*)>1)x),'accepted_without_version',(select count(*) from public.quotations where estado='aceptada' and version_aceptada is null),'duplicate_active_invoices',(select count(*) from (select reservation_id from public.invoices where estado<>'anulada' group by reservation_id having count(*)>1)x)),
 'columns',(select jsonb_agg(to_jsonb(c)) from (select table_schema,table_name,column_name,data_type,is_nullable from information_schema.columns where table_schema='public' and table_name in ('quotations','quotation_versions','reservations','reservation_items','payments','invoices','customers','reservation_travel','reservation_travel_history','reservation_passengers','payment_receipts','travel_deliveries') order by table_name,ordinal_position)c),
 'rls',(select jsonb_agg(jsonb_build_object('table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('reservations','reservation_items','payments','invoices','quotation_versions','customers','reservation_travel','payment_receipts')),
 'policies',(select jsonb_agg(to_jsonb(p)) from (select schemaname,tablename,policyname,roles,cmd,qual,with_check from pg_policies where (schemaname='public' and tablename in ('reservations','reservation_items','payments','invoices','quotation_versions','customers','reservation_travel','payment_receipts')) or schemaname='storage')p),
 'triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'trigger',t.tgname,'definition',pg_get_triggerdef(t.oid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal and c.relname in ('quotations','quotation_versions','reservations','reservation_items','payments','invoices')),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('quotations','quotation_versions','reservations','reservation_items','payments','invoices')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'security_definer',p.prosecdef,'arguments',pg_get_function_identity_arguments(p.oid),'acl',p.proacl)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('is_admin','accept_quotation','convert_accepted_quotation','save_reservation_record','create_reservation_invoice','save_reservation_travel','convert_quotation_with_passengers','create_payment_receipt')),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets),
 'migration_table',to_regclass('supabase_migrations.schema_migrations')
) as metadata;
commit;
